using System;
using System.IO;
using System.Collections.Generic;
public class CleanupRegression {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Write(string root,string relative){string p=Path.Combine(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,"fixture");}
 public static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string local=Path.Combine(root,"Local"),roaming=Path.Combine(root,"Roaming"),data=Path.Combine(root,"Client");Directory.CreateDirectory(local);Directory.CreateDirectory(roaming);var processes=new List<CleanupProcess>();var killed=new List<int>();bool deny=false;Action<CleanupProcess> kill=p=>{if(deny)throw new IOException("Negado");killed.Add(p.pid);processes.RemoveAll(x=>x.Key==p.Key);};Func<List<CleanupProcess>> read=()=>new List<CleanupProcess>(processes);long before=DateTime.UtcNow.AddMinutes(-1).Ticks;
  processes.Add(new CleanupProcess{pid=1,started=before,name="explorer",visible=true});processes.Add(new CleanupProcess{pid=2,started=before,name="admin-tool",visible=true});processes.Add(new CleanupProcess{pid=6,started=before,name="steam",visible=true});processes.Add(new CleanupProcess{pid=7,started=before+1,name="steamwebhelper",visible=false});
  var cleaner=new SessionCleanup(data,local,roaming,read,kill);cleaner.Begin("session-a");long during=DateTime.UtcNow.AddSeconds(1).Ticks;
  processes.Add(new CleanupProcess{pid=3,started=during,name="game",visible=true});processes.Add(new CleanupProcess{pid=4,parent=3,started=during+1,name="game-child"});processes.Add(new CleanupProcess{pid=5,started=during,name="chrome",visible=true});processes.Add(new CleanupProcess{pid=8,started=during+2,name="steam",visible=false});processes.Add(new CleanupProcess{pid=9,parent=8,started=during+3,name="steamwebhelper",visible=false});processes.Add(new CleanupProcess{pid=10,parent=8,started=during+4,name="GameOverlayUI",visible=false});cleaner.Observe();
  Write(local,"Google\\Chrome\\User Data\\Default\\Network\\Cookies");Write(local,"Google\\Chrome\\User Data\\Local State");Write(local,"BraveSoftware\\Brave-Browser\\User Data\\Default\\Cookies");Write(roaming,"Mozilla\\Firefox\\Profiles\\abc.default\\cookies.sqlite");Write(root,"Downloads\\keep.txt");Write(root,"Unrelated\\keep.txt");
  deny=true;try{cleaner.Clean();throw new Exception("Expected failure");}catch(IOException){}Check(cleaner.Pending,"Pending lost");Check(File.Exists(Path.Combine(local,"Google\\Chrome\\User Data\\Local State")),"Browser data changed during failed cleanup");
  deny=false;processes.RemoveAll(p=>p.pid==3);processes.Add(new CleanupProcess{pid=3,started=during+100,name="unrelated",visible=true});cleaner=new SessionCleanup(data,local,roaming,read,kill);cleaner.Clean();Check(!cleaner.Pending,"Still pending");Check(!killed.Contains(1)&&!killed.Contains(2)&&!killed.Contains(3)&&!killed.Contains(6)&&!killed.Contains(7),"Protected/baseline/PID reuse");Check(killed.Contains(4)&&killed.Contains(5)&&killed.Contains(8)&&killed.Contains(9)&&killed.Contains(10),"Processo iniciado apos login sobreviveu");
  Check(File.Exists(Path.Combine(local,"Google\\Chrome\\User Data\\Local State")),"Chrome profile was deleted");Check(File.Exists(Path.Combine(local,"BraveSoftware\\Brave-Browser\\User Data\\Default\\Cookies")),"Brave profile was deleted");Check(File.Exists(Path.Combine(roaming,"Mozilla\\Firefox\\Profiles\\abc.default\\cookies.sqlite")),"Firefox profile was deleted");Check(File.Exists(Path.Combine(root,"Downloads\\keep.txt"))&&File.Exists(Path.Combine(root,"Unrelated\\keep.txt")),"Unrelated files changed");
  cleaner.Begin("session-b");long later=DateTime.UtcNow.AddSeconds(2).Ticks;processes.Add(new CleanupProcess{pid=20,started=later,name="ChatGPT",visible=true});processes.Add(new CleanupProcess{pid=21,parent=20,started=later+1,name="ChatGPT",visible=false});cleaner.Observe();processes.RemoveAll(p=>p.pid==20);processes.Add(new CleanupProcess{pid=22,started=later+2,name="ChatGPT",visible=false});cleaner.Clean();Check(!cleaner.Pending,"Second cleanup remained pending");Check(killed.Contains(21)&&killed.Contains(22),"Tray/background respawn survived");
  Console.WriteLine("PASS: somente processos iniciados apos o login fecham; launchers/helpers anteriores sao preservados; filhos e respawns da sessao fecham; perfis e arquivos permanecem.");
 }
}
